<?php
declare(strict_types=1);
require_once dirname(__DIR__,2).'/system/app/bootstrap.php';
require_once dirname(__DIR__,2).'/system/ui/layout.php';
require_once __DIR__.'/system/VisualQueryBuilder.php';
require_once dirname(__DIR__,2).'/system/licensing/Autoload.php';
$user=enterprise_require_auth('../../');enterprise_require_customer_module($user,'dataform');
if(!enterprise_license_capability($user,'dataform.search')&&!enterprise_license_capability($user,'dataform.filter')){http_response_code(403);exit('Visual Queries sind in der aktuellen Lizenz nicht freigegeben.');}
$projectId=(int)($_GET['project']??$_POST['project']??($_SESSION['active_project_id']??0));
enterprise_require_project_scope($user,$projectId,false);
$dataformId=(int)($_GET['dataform']??$_POST['dataform']??0);$queryId=(int)($_GET['query']??$_POST['query']??0);
$error='';$success='';$project=null;$dataforms=[];$fields=[];$queries=[];$definition=['fields'=>[],'filters'=>[],'sort_field'=>'id','sort_direction'=>'ASC','limit'=>25];$result=null;
try{
 $admin=enterprise_pdo();enterprise_upgrade($admin);$s=$admin->prepare('SELECT * FROM projects WHERE id=? AND product_type=? LIMIT 1');$s->execute([$projectId,'dataform']);$project=$s->fetch();if(!$project)throw new RuntimeException('DataForm-Projekt wurde nicht gefunden.');$_SESSION['active_project_id']=$projectId;
 $env=enterprise_env(dirname(__DIR__,2).'/DataForm5-Core/.env');$pdo=enterprise_project_store_for_project($env,$project);VisualQueryBuilder::ensureSchema($pdo);
 $dataforms=$pdo->query('SELECT id,name,slug FROM dataforms ORDER BY name')->fetchAll();$dataforms=enterprise_filter_dataforms_for_scope($user,$projectId,$dataforms);if($dataformId<1&&$dataforms)$dataformId=(int)$dataforms[0]['id'];if($dataformId>0)enterprise_require_dataform_scope($user,$projectId,$dataformId);
 if($dataformId>0){$queryManifest=\EasyIT\Enterprise\Licensing\EnterpriseRuntimeBridge::boot(dirname(__DIR__,2),$projectId,$dataformId);$queryCaps=array_fill_keys(array_map('strval',(array)($queryManifest['capabilities']??[])),true);if(!isset($queryCaps['dataform.search'])&&!isset($queryCaps['dataform.filter']))throw new RuntimeException('Visual Queries sind für dieses DataForm nicht lizenziert.');$q=$pdo->prepare('SELECT id,label,name,field_type FROM dataform_fields WHERE dataform_id=? ORDER BY position,id');$q->execute([$dataformId]);$fields=$q->fetchAll();$fieldMap=[];foreach($fields as $f)$fieldMap[(string)$f['name']]=$f;
  if($queryId>0){$q=$pdo->prepare('SELECT * FROM dataform_queries WHERE id=? AND dataform_id=?');$q->execute([$queryId,$dataformId]);if($saved=$q->fetch())$definition=json_decode((string)$saved['definition_json'],true)?:$definition;}
  if($_SERVER['REQUEST_METHOD']==='POST'){enterprise_check_csrf((string)($_POST['csrf']??''));$action=(string)($_POST['action']??'preview');
   $raw=['fields'=>(array)($_POST['fields']??[]),'filters'=>[],'sort_field'=>(string)($_POST['sort_field']??'id'),'sort_direction'=>(string)($_POST['sort_direction']??'ASC'),'limit'=>(int)($_POST['limit']??25)];
   foreach((array)($_POST['filter_field']??[]) as $i=>$ff)$raw['filters'][]=['field'=>$ff,'operator'=>(string)(($_POST['filter_operator'][$i]??'equals')),'value'=>(string)(($_POST['filter_value'][$i]??''))];
   $definition=VisualQueryBuilder::normalizeDefinition($raw,$fieldMap);
   if($action==='save'){$name=trim((string)($_POST['query_name']??''));if($name==='')throw new RuntimeException('Bitte geben Sie einen Namen für die Abfrage ein.');$stmt=$pdo->prepare('INSERT INTO dataform_queries(dataform_id,name,description,definition_json,created_by) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE description=VALUES(description),definition_json=VALUES(definition_json),updated_at=CURRENT_TIMESTAMP');$stmt->execute([$dataformId,$name,trim((string)($_POST['description']??''))?:null,json_encode($definition,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),$user['id']??null]);$success='Abfrage wurde gespeichert.';}
   elseif($action==='delete'){$pdo->prepare('DELETE FROM dataform_queries WHERE id=? AND dataform_id=?')->execute([(int)$_POST['query_id'],$dataformId]);$queryId=0;$success='Abfrage wurde gelöscht.';}
   else{$result=VisualQueryBuilder::execute($pdo,$dataformId,$definition);}
  }
  $q=$pdo->prepare('SELECT * FROM dataform_queries WHERE dataform_id=? ORDER BY name');$q->execute([$dataformId]);$queries=$q->fetchAll();
 }
}catch(Throwable $e){$error=$e->getMessage();}
$selected=array_flip($definition['fields']??[]);ob_start();
?>
<div class="workspace-breadcrumbs"><?php render_breadcrumbs([['label'=>'Enterprise','href'=>'../../app/dashboard.php'],['label'=>'Projekte','href'=>'../../app/projects/index.php'],['label'=>(string)($project['name']??'DataForm'),'href'=>$project?'../../app/projects/view.php?id='.(int)$project['id']:''],['label'=>'DataForm Workspace','href'=>'index.php?project='.$projectId],['label'=>'Visual Query Builder','href'=>'']]);?></div>
<div class="df-workspace"><header class="df-workspace-header"><div><span class="badge">DataForm Workspace</span><h1>Visual Query Builder</h1><p>Abfragen ohne handgeschriebenes SQL zusammenstellen, prüfen und wiederverwenden.</p></div><div class="actions"><a class="button secondary" href="index.php?project=<?=$projectId?>">Zum Workspace</a></div></header>
