<div class="df-workspace-grid"><aside class="df-explorer"><div class="df-pane-title">Abfragen</div><nav><a href="index.php?project=<?=$projectId?>">Workspace</a><a class="active" href="queries.php?project=<?=$projectId?>">Visual Query Builder</a><?php foreach($queries as $q):?><a class="<?=$queryId===(int)$q['id']?'active':''?>" href="queries.php?project=<?=$projectId?>&dataform=<?=$dataformId?>&query=<?=(int)$q['id']?>">↳ <?=e((string)$q['name'])?></a><?php endforeach;?></nav></aside>
<main class="df-main"><section class="card"><form method="get" class="form-grid"><input type="hidden" name="project" value="<?=$projectId?>"><label>DataForm<select name="dataform" onchange="this.form.submit()"><?php foreach($dataforms as $d):?><option value="<?=(int)$d['id']?>" <?=$dataformId===(int)$d['id']?'selected':''?>><?=e((string)$d['name'])?></option><?php endforeach;?></select></label></form></section>
<?php if($dataformId>0):?><form method="post"><input type="hidden" name="csrf" value="<?=e(enterprise_csrf())?>"><input type="hidden" name="project" value="<?=$projectId?>"><input type="hidden" name="dataform" value="<?=$dataformId?>"><section class="card"><h2>1. Ausgabefelder</h2><div class="query-field-grid"><?php foreach($fields as $f):?><label><input type="checkbox" name="fields[]" value="<?=e((string)$f['name'])?>" <?=isset($selected[(string)$f['name']])?'checked':''?>> <?=e((string)$f['label'])?> <small><code><?=e((string)$f['name'])?></code></small></label><?php endforeach;?></div></section>
<section class="card"><h2>2. Filter</h2><div id="query-filters"><?php $rows=$definition['filters']?:[['field'=>'','operator'=>'equals','value'=>'']];foreach($rows as $r):?><div class="query-filter-row"><select name="filter_field[]"><option value="">– kein Feld –</option><?php foreach($fields as $f):?><option value="<?=e((string)$f['name'])?>" <?=$r['field']===$f['name']?'selected':''?>><?=e((string)$f['label'])?></option><?php endforeach;?></select><select name="filter_operator[]"><?php foreach(['equals'=>'gleich','not_equals'=>'ungleich','contains'=>'enthält','starts_with'=>'beginnt mit','empty'=>'ist leer','not_empty'=>'ist nicht leer','greater'=>'größer','less'=>'kleiner'] as $k=>$v):?><option value="<?=$k?>" <?=$r['operator']===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select><input name="filter_value[]" value="<?=e((string)$r['value'])?>" placeholder="Vergleichswert"></div><?php endforeach;?></div><button type="button" class="button secondary" onclick="addQueryFilter()">+ Filterzeile</button></section>
<section class="card"><h2>3. Sortierung und Limit</h2><div class="form-grid"><label>Sortierfeld<select name="sort_field"><option value="id">ID</option><option value="updated_at" <?=$definition['sort_field']==='updated_at'?'selected':''?>>Geändert am</option><?php foreach($fields as $f):?><option value="<?=e((string)$f['name'])?>" <?=$definition['sort_field']===$f['name']?'selected':''?>><?=e((string)$f['label'])?></option><?php endforeach;?></select></label><label>Richtung<select name="sort_direction"><option value="ASC">Aufsteigend</option><option value="DESC" <?=$definition['sort_direction']==='DESC'?'selected':''?>>Absteigend</option></select></label><label>Maximale Treffer<input type="number" min="1" max="200" name="limit" value="<?=(int)$definition['limit']?>"></label></div></section>
<section class="card"><h2>4. Vorschau oder speichern</h2><div class="form-grid"><label>Abfragename<input name="query_name" placeholder="z. B. Aktive Kunden"></label><label class="full">Beschreibung<textarea name="description" rows="2"></textarea></label><div class="full actions"><button class="button" name="action" value="preview">Vorschau ausführen</button><button class="button secondary" name="action" value="save">Abfrage speichern</button><?php if($queryId):?><input type="hidden" name="query_id" value="<?=$queryId?>"><button class="link-danger" name="action" value="delete" onclick="return confirm('Abfrage löschen?')">Löschen</button><?php endif;?></div></div></section></form>
<?php if($result):?><section class="card"><h2>Ergebnisvorschau</h2><p><?=count($result['rows'])?> Treffer. Es wurden ausschließlich lesende SELECT-Abfragen ausgeführt.</p><details><summary>Generiertes SQL anzeigen</summary><pre><?=e($result['sql'])?></pre></details><?php if($result['rows']):?><div class="table-wrap"><table><thead><tr><?php foreach(array_keys($result['rows'][0]) as $c):?><th><?=e($c)?></th><?php endforeach;?></tr></thead><tbody><?php foreach($result['rows'] as $row):?><tr><?php foreach($row as $v):?><td><?=e((string)$v)?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty-state">Keine Treffer.</div><?php endif;?></section><?php endif;?><?php endif;?></main>
<aside class="df-properties"><div class="df-pane-title">Kontexthilfe</div><h3>Ziel</h3><p>Felder, Filter und Sortierung visuell zu einer sicheren Leseabfrage kombinieren.</p><h3>Sicherheit</h3><p>Der Builder erzeugt ausschließlich SELECT-Abfragen. Tabellen- und Feldnamen stammen aus dem DataForm-Modell.</p><h3>Filter</h3><p>Mehrere Filter werden mit UND verknüpft.</p><h3>Nächster Schritt</h3><p>Gespeicherte Abfragen können später als Quelle für Dashboard, Reports und API verwendet werden.</p></aside></div></div>
